#!/usr/bin/env bash
# Run from the root of your X-ReMap checkout, after the tray-and-animations patch.
# Makes the tray app test hermetic (no real controllers) and self-terminating, then runs the tests.
set -euo pipefail
git rev-parse --show-toplevel >/dev/null 2>&1 || { echo "Run this inside your X-ReMap git checkout." >&2; exit 1; }
echo '' | base64 -d | gunzip | git apply --verbose && python3 -m unittest discover -s tests && echo ALL_APPLIED_AND_PASSING
